INSERT OR REPLACE INTO manual_sections
  (manual_key, section_key, title, body, sort_order, version, updated_by, updated_at)
VALUES
  ('owner','staff-availability-schedule','Staff Availability Timer & Schedule','Staff availability ကို Asia/Yangon (UTC+06:30) ဖြင့် private bot chat သို့မဟုတ် active Staff Inbox group ထဲကနေ စီမံနိုင်ပါတယ်။ Active Staff Inbox group မရှိရင် private availability command က state မပြောင်းဘဲ reject လုပ်မယ်။ Private ကပြောင်းလိုက်တဲ့ state/timer/schedule update ကို Staff Inbox group root ထဲ team coordination အတွက် အလိုအလျောက်ပြမယ်။\n\nCommands:\n/available = immediate available; recurring schedule ကို clear\n/unavailable = indefinite unavailable\n/unavailable 3 = 3 hours temporary unavailable\n/unavailable cancel = active temporary unavailable timer ကိုပယ်ဖျက်; recurring schedule ရှိရင် schedule state ပြန်ဝင်၊ မရှိရင် available ပြန်ဖြစ်\n/available 09:00 17:00 = daily recurring 09:00–17:00 schedule\n/available 9am 5pm = အထက်ပါ alias\n/available 20:00 08:00 = overnight schedule\n/available cancel = recurring daily schedule ကိုပယ်ဖျက်ပြီး ပယ်ဖျက်ချိန် current effective AVAILABLE/UNAVAILABLE state ကို manual state အဖြစ်ဆက်ထား\n\n`cancel` အစား `clear` ကို alias အဖြစ်လည်း သုံးနိုင်ပါတယ်။ Temporary timer expiry သို့ daily schedule start/end ကြောင့် effective state တကယ်ပြောင်းသွားရင် existing 5-minute Cron က state update လုပ်ပြီး staff private chat နှင့် Staff Inbox group နှစ်ဖက်လုံးသို့ one-time Staff availability auto-update notice ပို့ပါတယ်။ Timer ပြည့်ပေမဲ့ recurring schedule အရ state မပြောင်းသေးရင် false transition notice မပို့ပါ။ Practical automatic transition latency 0–5 minutes ဖြစ်နိုင်ပါတယ်။',97,3,0,CURRENT_TIMESTAMP),
  ('admin','staff-availability-schedule','Staff Availability Timer & Schedule','/available နှင့် /unavailable ကို authorized staff အဖြစ် private bot chat သို့မဟုတ် active Staff Inbox group ထဲကနေ သုံးနိုင်ပါတယ်။ Private use အတွက် active Staff Inbox group configured ဖြစ်ရမယ်၊ successful private changes ကို group root ထဲ team coordination အတွက် ပြန်တင်ပါတယ်။\n\n/unavailable 3 = 3 hours temporary unavailable\n/unavailable cancel = temporary timer ပယ်ဖျက်; schedule ရှိရင် schedule state ပြန်ဝင်\n/available 09:00 17:00 သို့ /available 9am 5pm = Asia/Yangon daily schedule\n/available cancel = recurring schedule ပယ်ဖျက်ပြီး current effective state ကို manual state အဖြစ်ထား\n\n`clear` ကို `cancel` alias အဖြစ်သုံးနိုင်ပါတယ်။ Timer expiry သို့ daily schedule start/end ကြောင့် effective state ပြောင်းသွားရင် staff private chat နှင့် Staff Inbox group နှစ်ဖက်လုံးမှာ automatic state-change notice တစ်ကြိမ်ပို့ပါတယ်။ Cron interval ကြောင့် 0–5 minutes latency ရှိနိုင်ပါတယ်။',97,3,0,CURRENT_TIMESTAMP),
  ('owner','owner-commands','3. Owner commands','/start — bot ကို စတင်သုံးရန်\n/whoami — ကိုယ့် Telegram name/username/ID ကိုကြည့်ရန်\n/admin — administrator tools\n/admins — လက်ရှိ authorized admins ကြည့်ရန်\n/faq — FAQ knowledge ကို add/edit/disable/restore လုပ်ရန်\n/cases — escalation cases ကိုကြည့်ရန်\n/limits — user rate limits/restrictions စီမံရန်\n/adminmanual — Sudo Admin manual ကိုဖတ်ရန်\n/noti on|off — Staff Inbox notification mode (active Staff Inbox group ထဲမှာသာ)\n/available — immediate available\n/available 09:00 17:00 သို့ /available 9am 5pm — Asia/Yangon daily availability schedule\n/available cancel — recurring availability schedule ပယ်ဖျက်ပြီး current state ကို manual state အဖြစ်ထား\n/unavailable — indefinite unavailable\n/unavailable 3 — 3 hours temporary unavailable\n/unavailable cancel — temporary unavailable timer ပယ်ဖျက်\n/sudo — Sudo Admin access grant/revoke\n/ai — AI provider/model/credentials စီမံရန်\n/staff — Staff Inbox, routing, monitoring စီမံရန်\n/clearmessage — recent Staff Inbox messages clear\n/ownermanual — Owner manual ဖတ်/edit\n/cancel — လက်ရှိ setup/edit wizard ကိုပယ်ဖျက်\n/reset — transient conversation state reset\n\n/available နှင့် /unavailable ကို private bot chat သို့ active Staff Inbox group ထဲမှာသုံးနိုင်ပြီး private use အတွက် Staff Inbox group configured ဖြစ်ရမယ်။ `cancel` အစား `clear` alias လည်းရပါတယ်။ Automatic timer/schedule state transitions ကို staff private + Staff Inbox နှစ်ဖက်လုံးသို့ declare လုပ်ပါတယ်။',30,3,0,CURRENT_TIMESTAMP),
  ('admin','commands','2. Admin commands','/start — bot ကို စတင်သုံးရန်\n/whoami — ကိုယ့် Telegram identity နဲ့ numeric ID ကြည့်ရန်\n/admin — administrator tools\n/admins — authorized administrators စာရင်းကြည့်ရန်\n/faq — FAQ knowledge ကို add/edit/disable/restore လုပ်ရန်\n/cases — escalation cases review\n/limits — user rate limits/restrictions review\n/adminmanual — ဒီ Admin manual ကိုဖတ်ရန်\n/noti on|off — active Staff Inbox group ထဲမှာ Staff Inbox notifications ပြောင်းရန်\n/available — immediate available\n/available 09:00 17:00 သို့ /available 9am 5pm — Asia/Yangon daily schedule\n/available cancel — recurring schedule ပယ်ဖျက်ပြီး current effective state ကို manual state အဖြစ်ထား\n/unavailable — indefinite unavailable\n/unavailable 3 — 3 hours temporary unavailable\n/unavailable cancel — temporary timer ပယ်ဖျက်\n/cancel — လက်ရှိ setup/edit wizard ကိုပယ်ဖျက်ရန်\n\n/available နှင့် /unavailable ကို private bot chat သို့ active Staff Inbox group မှာသုံးနိုင်ပါတယ်။ Private use အတွက် Staff Inbox group configured ဖြစ်ရမယ်။ `clear` ကို `cancel` alias အဖြစ်လည်းသုံးနိုင်ပါတယ်။ Automatic timer/schedule state transition ဖြစ်ရင် private + group နှစ်ဖက်လုံး update တက်ပါတယ်။ Owner-only /sudo, /ai, /staff, /ownermanual တို့ကို Sudo Admin မပြောင်းနိုင်ပါ။',20,3,0,CURRENT_TIMESTAMP);
